class GraphInterrupt(Exception):
    def __init__(self, payload): self.payload = payload

def helper_deep():
    raise GraphInterrupt({'ask': 'Approve?'})

def business_node():
    helper_deep()  # 无需层层写 if paused: return!
    return {'done': True}

try:
    business_node()
except GraphInterrupt as g:
    print('Intercepted by Loop:', g.payload)
